// Guides that belong to API → Getting Started (docs/API/sidebar.js), the API reading path:
// Introduction → Generate Documents → these, in this order → Resources and Endpoints.
// A page sits in the Previous / Next order once, so their own sections (TurboSign, TurboDocx Templating,
// both autogenerated) list them as shortcuts (`ref`) instead: still shown there, skipped by Previous / Next.
// Checked by scripts/sidebar.test.mjs.
const GETTING_STARTED_GUIDES = [
  {id: 'TurboSign/API-Signatures', label: 'Send for Signature'},
  {id: 'TurboSign/API-Bulk-Signatures', label: 'Bulk Signatures'},
  {id: 'TurboDocx-Templating/API-Templates', label: 'Templates'},
  {id: 'TurboSign/Webhooks', label: 'Webhooks'},
];

const GUIDE_IDS = new Set(GETTING_STARTED_GUIDES.map(({id}) => id));

// Turn the guides into shortcuts anywhere in an autogenerated sidebar (sidebarItemsGenerator output).
function guidesAsShortcuts(items) {
  return items.map((item) => {
    if (item.type === 'doc' && GUIDE_IDS.has(item.id)) {
      return {...item, type: 'ref'};
    }
    if (item.type === 'category') {
      return {...item, items: guidesAsShortcuts(item.items)};
    }
    return item;
  });
}

module.exports = {GETTING_STARTED_GUIDES, guidesAsShortcuts};
